    for r in range(h):
        # Most rows follow base phase 2 (color 3) in 1-index terms,
        # except initial shifted pattern rows whose unmasked evidence sets it.
        candidates = []
        for c, v in enumerate(grid[r]):
            if v == 0:
                continue
            # diagonal pixels are the overlay and not the underlying sequence
            if c == r:
                continue
            candidates.append((idx[v] - c) % n)
        if candidates:
            # dominant phase from the row's intact sequence
            phase = max(set(candidates), key=candidates.count)
        else:
            phase = 0
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = colors[(phase + c) % n]
    return out


