def transform(grid):
    """Fill erased cells using the dominant cyclic progression in each row."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Rows follow a 1..9 cycle with a row-specific phase. Existing diagonal
        # duplicates/local marks are outliers, so use the modal phase offset.
        offsets = [((value - 1 - c) % 9)
                   for c, value in enumerate(row) if value != 0]
        phase = Counter(offsets).most_common(1)[0][0] if offsets else 0
        for c, value in enumerate(row):
            if value == 0:
                out[r][c] = (phase + c) % 9 + 1
    return out


