 "content": "def transform(grid):
    # Each row has an ascending modulo-9 progression with one duplicated value
    # on the diagonal. Zero masks hide cells; restore them from the pattern.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        # The row phase is inferred from the intact values, robustly ignoring
        # the diagonal duplicate and any isolated anomalies by modal offset.
        offsets = [(grid[r][c] - 1 - c) % 9
                   for c in range(w) if grid[r][c] != 0 and c != r]
        if offsets:
            phase = max(set(offsets), key=offsets.count)
        else:
            phase = 0
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = (phase + c) % 9 + 1
    return out


