 "content": "def transform(grid):
    """Restore zero masks in a cyclic row pattern with a diagonal repeat."""
    h, w = len(grid), len(grid[0])
    cycle = max(max(row) for row in grid)
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        # The first row has no diagonal repeat; later rows repeat the
        # preceding cyclic value at column r, shifting the sequence thereafter.
        best_start = 1
        best_matches = -1
        for start in range(1, cycle + 1):
            matches = 0
            for c, value in enumerate(row):
                if value == 0:
                    continue
                offset = c if r == 0 or c < r else c - 1
                expected = (start - 1 + offset) % cycle + 1
                if value == expected:
                    matches += 1
            if matches > best_matches:
                best_matches = matches
                best_start = start

        for c, value in enumerate(row):
            if value == 0:
                offset = c if r == 0 or c < r else c - 1
                out[r][c] = (best_start - 1 + offset) % cycle + 1
    return out


